DROP POLICY IF EXISTS "marketplace_settings_select" ON public.marketplace_settings;
CREATE POLICY "marketplace_settings_select_signed_in" ON public.marketplace_settings FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "avatar_item_base_variants_select" ON public.avatar_item_base_variants;
CREATE POLICY "avatar_item_base_variants_select_signed_in" ON public.avatar_item_base_variants FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "avatar_profiles_select" ON public.avatar_profiles;
CREATE POLICY "avatar_profiles_select_signed_in" ON public.avatar_profiles FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Anyone authenticated can view study methods" ON public.study_methods;
CREATE POLICY "Signed in can view study methods" ON public.study_methods FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Authenticated can read subjects" ON public.subjects;
CREATE POLICY "Signed in can read subjects" ON public.subjects FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Anyone authenticated can read methods" ON public.learning_methods;
CREATE POLICY "Signed in can read methods" ON public.learning_methods FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Anyone can read articles" ON public.articles;
CREATE POLICY "Published articles or admin" ON public.articles FOR SELECT TO public USING (status = 'published' OR public.is_admin());
DROP POLICY IF EXISTS "Anyone can read podcast_episodes" ON public.podcast_episodes;
CREATE POLICY "Published podcast episodes or admin" ON public.podcast_episodes FOR SELECT TO public USING (status = 'published' OR public.is_admin());
DROP POLICY IF EXISTS "Landing sections are readable by everyone" ON public.landing_sections;
CREATE POLICY "Enabled landing sections or admin" ON public.landing_sections FOR SELECT TO public USING (enabled = true OR public.is_admin());
DROP POLICY IF EXISTS "Anyone can read section_links" ON public.section_links;
CREATE POLICY "Section links readable by everyone" ON public.section_links FOR SELECT TO public USING (id IS NOT NULL);